config.script:
// Generated from Pingdom transaction check "Acme checkout recording" (recording).
var page = browser.open();
function must(r, what) { if (!r.ok) { throw new Error(what + ": " + r.error); } }
function waitText(what, sel, value, isRegex, want, seconds) {
  var tries = Math.max(1, Math.ceil(seconds * 2));
  var has = false;
  for (var i = 0; i < tries; i++) {
    var t = page.text(sel);
    has = t.ok && (isRegex ? new RegExp(value).test(t.text) : t.text.indexOf(value) >= 0);
    if (has === want) { return; }
    if (i < tries - 1) { sleep(500); }
  }
  throw new Error(what + ": " + (want ? "text not found" : "text still present") + " in " + sel);
}
must(page.basicAuth(secrets.PINGDOM_BASIC_USER, secrets.PINGDOM_BASIC_PASSWORD), "basic_auth");
step("Go to \"https://shop.acme.example\"", function () {
  must(page.goto("https://shop.acme.example"), "step 1: wpm_go_to https://shop.acme.example");
});
step("Click \"Buy\"", function () {
  must(page.click("auto=Buy"), "step 2: wpm_click Buy");
});
step("Fill \"Qty\"", function () {
  must(page.fill("auto=Qty", "2"), "step 3: wpm_fill Qty");
});
step("Select dropdown \"size\"", function () {
  must(page.select("auto=size", "L"), "step 4: wpm_select_dropdown size");
});
step("Wait", function () {
  sleep(2000);
});
step("Contains timeout \"body\"", function () {
  waitText("step 6: wpm_contains_timeout body", "auto=body", "Order \\d+", true, true, 5);
});
step("Not contains timeout \"body\"", function () {
  waitText("step 7: wpm_not_contains_timeout body", "auto=body", "Error", false, false, 1);
});
// TODO step 8: "wpm_click_xy" has no SolidPing equivalent (coordinate, hover and tab steps are not supported)
return { status: "up", output: { url: page.url() } };
